fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since lengths are equal, zip is safe
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x >= y)
     .collect()
}